from flask import Flask, jsonify, request
import random
app = Flask(__name__)
def ai_predict(t1,t2):
 s1=random.randint(0,3);s2=random.randint(0,3)
 if s1==s2: s1+=1
 tot=s1+s2+1;w1=int((s1+1)/tot*65+random.randint(-10,10));w2=int((s2+1)/tot*65+random.randint(-10,10));dr=100-w1-w2
 if dr<10: dr=15
 conf=random.randint(72,94);anal=f"تحليل AI: {t1} هجومه قوي، {t2} دفاعه صلب"
 return {"score":f"{s1} - {s2}","win1":w1,"win2":w2,"draw":dr,"confidence":conf,"analysis":anal,"goals":"Over 2.5"}
@app.route('/')
def home():
 return '<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shaam Sport AI</title><script src="https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js"></script><style>body{background:#0a0a0a;color:#fff;padding:15px;font-family:system-ui}.card{background:#1a1a1a;padding:20px;border-radius:20px;margin-bottom:15px;border:1px solid #333}input,select{width:100%;padding:15px;border-radius:12px;background:#222;color:#fff;border:1px solid #444;margin:10px 0}.btn{width:100%;padding:15px;border-radius:12px;border:none;font-weight:900;font-size:18px;margin-top:10px}.btn-green{background:#00ff88}.btn-cam{background:linear-gradient(135deg,#ff00aa,#ff8800);color:#fff}#preview{width:100%;border-radius:15px;margin-top:10px;display:none}#ocr{background:#111;padding:10px;border-radius:10px;margin-top:10px;display:none;white-space:pre-wrap}.bar{height:10px;background:#333;border-radius:10px;overflow:hidden;display:flex;margin:5px 0}.bar div{height:100%}</style></head><body><div style="text-align:center;padding:20px;background:linear-gradient(135deg,#00ff88,#00aaff);border-radius:20px;color:#000;margin-bottom:15px"><h1>⚽ Shaam Sport AI</h1><p>كل الدوريات + كاميرا OCR</p></div><div class="card"><h3>📸 صور جدول المباريات</h3><input type="file" id="cam" accept="image/*" capture="environment" style="display:none"><button class="btn btn-cam" onclick="document.getElementById(&quot;cam&quot;).click()">📸 افتح الكاميرا</button><img id="preview"><div id="ocr"></div></div><div class="card"><h3>🎯 توقع نتيجة</h3><input id="t1" placeholder="الفريق الاول - ريال مدريد"><input id="t2" placeholder="الفريق الثاني - برشلونة"><button class="btn btn-green" onclick="predict()">🤖 حلل وتوقع</button><div id="res" style="display:none;margin-top:15px;background:#000;padding:15px;border-radius:15px;border:1px dashed #00ff88"></div></div><script>let lastText="";document.getElementById("cam").addEventListener("change",async e=>{let f=e.target.files[0];if(!f)return;let img=document.getElementById("preview");img.src=URL.createObjectURL(f);img.style.display="block";let o=document.getElementById("ocr");o.style.display="block";o.innerText="⏳ يقرأ الصورة...";try{let {data:{text}}=await Tesseract.recognize(f,"eng+ara");lastText=text;o.innerText="✅ النص:\\n"+text;if(text.includes("-")||text.toLowerCase().includes("vs")){let parts=text.split("\\n")[0].split(/vs|-|–/);document.getElementById("t1").value=parts[0];document.getElementById("t2").value=parts[1]||"";}}catch(e){o.innerText="❌ صورة غير واضحة";}});async function predict(){let a=document.getElementById("t1").value||"ريال مدريد";let b=document.getElementById("t2").value||"برشلونة";let box=document.getElementById("res");box.style.display="block";box.innerHTML="⏳ AI يحلل...";let r=await fetch("/api/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({team1:a,team2:b})}).then(x=>x.json());box.innerHTML=`<h2 style="text-align:center;font-size:30px">${r.score}</h2><p style="text-align:center;color:#00ff88">ثقة ${r.confidence}%</p><div style="margin-top:10px"><div style="display:flex;justify-content:space-between"><span>${a}</span><span>${r.win1}%</span></div><div class="bar"><div style="width:${r.win1}%;background:#00ff88"></div></div><div style="display:flex;justify-content:space-between"><span>تعادل</span><span>${r.draw}%</span></div><div class="bar"><div style="width:${r.draw}%;background:#888"></div></div><div style="display:flex;justify-content:space-between"><span>${b}</span><span>${r.win2}%</span></div><div class="bar"><div style="width:${r.win2}%;background:#00aaff"></div></div></div><p style="margin-top:10px;background:#111;padding:10px;border-radius:10px">🤖 ${r.analysis}</p>`;}</script></body></html>'
@app.route('/api/analyze',methods=['POST'])
def analyze():
 d=request.json;return jsonify(ai_predict(d.get('team1','A'),d.get('team2','B')))
@app.route('/manifest.json')
def mf():
 return jsonify({"name":"Shaam Sport AI","short_name":"Shaam Sport","start_url":"/","display":"standalone","background_color":"#0a0a0a","theme_color":"#00ff88","icons":[{"src":"https://cdn-icons-png.flaticon.com/512/1165/1165407.png","sizes":"512x512","type":"image/png"}]})
if __name__=='__main__':
 app.run(host='0.0.0.0',port=10000)
